import { useNavigation } from "@react-navigation/native";
import React, { useState } from "react";
import { Alert, Image, Pressable, Text, View } from "react-native";
import { TRACKS } from "../data";
import { useStore } from "../store";
import { fonts, useTheme } from "../theme";
import { Button, Field, H1, P, PasswordField, Screen } from "../ui";

function Link({ title, onPress }: { title: string; onPress: () => void }) {
  const t = useTheme();
  return <Pressable onPress={onPress} style={{ paddingVertical: 10 }}><Text style={{ fontFamily: fonts.bodyBold, color: t.primary, textAlign: "center" }}>{title}</Text></Pressable>;
}

function SignIn() {
  const nav = useNavigation<any>();
  const { signIn } = useStore();
  const [email, setEmail] = useState("");
  const [pw, setPw] = useState("");
  return (
    <Screen>
      <Image source={require("../../assets/logo.png")} style={{ width: 160, height: 70, alignSelf: "center", marginBottom: 12 }} resizeMode="contain" />
      <H1>Welcome back.</H1>
      <P style={{ marginBottom: 18 }}>Demo: any email and password will sign you in.</P>
      <Field label="Email" value={email} onChangeText={setEmail} placeholder="you@example.com" keyboardType="email-address" autoCapitalize="none" />
      <PasswordField label="Password" value={pw} onChangeText={setPw} placeholder="Your password" />
      <Link title="Forgot password?" onPress={() => nav.navigate("ForgotPassword")} />
      <Button title="Sign in" onPress={() => {
        if (!email.includes("@") || pw.length < 1) return Alert.alert("Check your details", "Enter a valid email and password.");
        signIn(email);
        nav.navigate("Tabs", { screen: "Account" });
      }} />
      <Link title="New here? Join RSVP DXB" onPress={() => nav.navigate("Register")} />
    </Screen>
  );
}

function Register() {
  const t = useTheme();
  const nav = useNavigation<any>();
  const { register } = useStore();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [pw, setPw] = useState("");
  const [track, setTrack] = useState(TRACKS[1].name as string);
  return (
    <Screen>
      <H1>Get on the list.</H1>
      <Field label="Full name" value={name} onChangeText={setName} placeholder="Your name" />
      <Field label="Email" value={email} onChangeText={setEmail} placeholder="you@example.com" keyboardType="email-address" autoCapitalize="none" />
      <PasswordField label="Password" value={pw} onChangeText={setPw} placeholder="At least 8 characters" />
      <Text style={{ fontFamily: fonts.bodyBold, color: t.text, marginBottom: 8 }}>Your track</Text>
      <View style={{ gap: 8, marginBottom: 18 }}>
        {TRACKS.map((tr) => (
          <Pressable key={tr.name} onPress={() => setTrack(tr.name)} style={{ padding: 14, borderRadius: 16, borderWidth: 1.5, borderColor: track === tr.name ? t.primary : t.border, backgroundColor: t.surface }}>
            <Text style={{ fontFamily: fonts.display, fontSize: 22, color: t.text }}>{tr.name}</Text>
            <P>{tr.blurb}</P>
          </Pressable>
        ))}
      </View>
      <Button title="Create account" onPress={() => {
        if (!name || !email.includes("@") || pw.length < 8) return Alert.alert("Check your details", "Name, valid email and an 8+ character password are required.");
        register(name, email, track);
        nav.navigate("Tabs", { screen: "Account" });
      }} />
    </Screen>
  );
}

function Forgot() {
  const nav = useNavigation<any>();
  const [email, setEmail] = useState("");
  return (
    <Screen>
      <H1>Forgot password?</H1>
      <P style={{ marginBottom: 18 }}>Enter your email and we'll send a reset link. (Demo: no email is sent — you'll go straight to the reset screen.)</P>
      <Field label="Email" value={email} onChangeText={setEmail} placeholder="you@example.com" keyboardType="email-address" autoCapitalize="none" />
      <Button title="Send reset link" onPress={() => {
        if (!email.includes("@")) return Alert.alert("Check your email", "Enter a valid email address.");
        nav.navigate("ResetPassword");
      }} />
    </Screen>
  );
}

function Reset() {
  const nav = useNavigation<any>();
  const [a, setA] = useState("");
  const [b, setB] = useState("");
  return (
    <Screen>
      <H1>Choose a new password.</H1>
      <PasswordField label="New password" value={a} onChangeText={setA} placeholder="At least 8 characters" />
      <PasswordField label="Confirm password" value={b} onChangeText={setB} placeholder="Repeat password" />
      <Button title="Reset password" onPress={() => {
        if (a.length < 8) return Alert.alert("Too short", "Use at least 8 characters.");
        if (a !== b) return Alert.alert("Passwords don't match", "Please type the same password twice.");
        Alert.alert("Password updated", "You can now sign in.");
        nav.navigate("SignIn");
      }} />
    </Screen>
  );
}

export const AuthScreens = { SignIn, Register, Forgot, Reset };
