import AsyncStorage from "@react-native-async-storage/async-storage";
import React, { createContext, useContext, useEffect, useState } from "react";
import { EVENTS, EventItem, RsvpState } from "./data";

export interface MemberProfile {
  name: string;
  email: string;
  phone: string;
  track: string;
  rank: string;
  points: number;
  memberId: string;
  photo?: string;
}

const DEMO_MEMBER: MemberProfile = {
  name: "Tejas Nair",
  email: "tejas@example.com",
  phone: "+971 50 000 0000",
  track: "Creators",
  rank: "Gold",
  points: 640,
  memberId: "RSVP-0142",
};

interface Store {
  ready: boolean;
  events: EventItem[];
  member: MemberProfile | null;
  rsvps: Record<string, RsvpState>;
  signIn: (email: string) => void;
  register: (name: string, email: string, track: string) => void;
  signOut: () => void;
  updateMember: (patch: Partial<MemberProfile>) => void;
  rsvp: (eventId: string) => RsvpState;
  cancelRsvp: (eventId: string) => void;
}

const Ctx = createContext<Store | null>(null);
const KEY = "rsvp-dxb-state-v1";

export function StoreProvider({ children }: { children: React.ReactNode }) {
  const [ready, setReady] = useState(false);
  const [member, setMember] = useState<MemberProfile | null>(null);
  const [rsvps, setRsvps] = useState<Record<string, RsvpState>>({});
  const [events, setEvents] = useState<EventItem[]>(EVENTS);

  useEffect(() => {
    AsyncStorage.getItem(KEY)
      .then((raw) => {
        if (raw) {
          const s = JSON.parse(raw);
          setMember(s.member ?? null);
          setRsvps(s.rsvps ?? {});
        }
      })
      .finally(() => setReady(true));
  }, []);

  useEffect(() => {
    if (ready) AsyncStorage.setItem(KEY, JSON.stringify({ member, rsvps }));
  }, [member, rsvps, ready]);

  const value: Store = {
    ready,
    events,
    member,
    rsvps,
    signIn: (email) => setMember({ ...DEMO_MEMBER, email: email || DEMO_MEMBER.email }),
    register: (name, email, track) => setMember({ ...DEMO_MEMBER, name, email, track, rank: "Bronze", points: 25 }),
    signOut: () => {
      setMember(null);
      setRsvps({});
    },
    updateMember: (patch) => setMember((m) => (m ? { ...m, ...patch } : m)),
    rsvp: (eventId) => {
      const ev = events.find((e) => e.id === eventId);
      if (!ev) return "none";
      const state: RsvpState = ev.confirmed >= ev.capacity ? "waitlist" : "going";
      setRsvps((r) => ({ ...r, [eventId]: state }));
      if (state === "going") setEvents((list) => list.map((e) => (e.id === eventId ? { ...e, confirmed: e.confirmed + 1 } : e)));
      return state;
    },
    cancelRsvp: (eventId) => {
      if (rsvps[eventId] === "going") setEvents((list) => list.map((e) => (e.id === eventId ? { ...e, confirmed: e.confirmed - 1 } : e)));
      setRsvps((r) => ({ ...r, [eventId]: "none" }));
    },
  };
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useStore() {
  const s = useContext(Ctx);
  if (!s) throw new Error("useStore must be used inside StoreProvider");
  return s;
}
